const state={key:sessionStorage.getItem("lcs_dispatch_key")||"",loads:[],filter:"ALL",timer:null};
const $=id=>document.getElementById(id);
$("loginForm").addEventListener("submit",async event=>{event.preventDefault();state.key=$("adminKey").value.trim();sessionStorage.setItem("lcs_dispatch_key",state.key);await refresh(true)});
$("refresh").addEventListener("click",()=>refresh());
$("signout").addEventListener("click",()=>{sessionStorage.removeItem("lcs_dispatch_key");location.reload()});
$("filters").addEventListener("click",event=>{const button=event.target.closest("button[data-filter]");if(!button)return;state.filter=button.dataset.filter;document.querySelectorAll("#filters button").forEach(x=>x.classList.toggle("active",x===button));render()});
$("loads").addEventListener("click",async event=>{const button=event.target.closest("button[data-action]");if(!button)return;button.disabled=true;const id=button.dataset.id;try{await api(`/api/dispatch-center/loads/${id}/${button.dataset.action}`,{method:"POST",body:JSON.stringify({claimedBy:"Wil / LCS Dispatch"})});message(button.dataset.action==="claim"?`Shipment #${id} claimed by LCS.`:`Shipment #${id} released to fallback.`);await refresh()}catch(error){message(error.message,true)}finally{button.disabled=false}});
async function api(path,options={}){const response=await fetch(path,{...options,headers:{"content-type":"application/json","x-admin-key":state.key,...options.headers}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data}
async function refresh(first=false){if(!state.key)return showLogin();try{const data=await api("/api/dispatch-center/loads");state.loads=data.loads||[];$("signin").hidden=true;$("board").hidden=false;document.body.classList.add("online");$("connection").textContent="Live · refreshes every 5 seconds";render();if(first)message("Live dispatch board connected.")}catch(error){document.body.classList.remove("online");$("connection").textContent="Connection failed";if(first){sessionStorage.removeItem("lcs_dispatch_key");state.key="";showLogin();message(error.message,true)}}}
function render(){const visible=state.loads.filter(x=>state.filter==="ALL"||x.shipment_category===state.filter);$("availableCount").textContent=state.loads.filter(x=>x.claim_status==="LCS_PRIORITY").length;$("claimedCount").textContent=state.loads.filter(x=>x.claim_status==="CLAIMED").length;$("fallbackCount").textContent=state.loads.filter(x=>["FALLBACK_PENDING","OFFERED"].includes(x.claim_status)).length;$("loads").innerHTML=visible.length?visible.map(card).join(""):'<div class="empty">No active food shipments in this view.</div>'}
function card(load){const priority=load.claim_status==="LCS_PRIORITY";const remaining=Math.max(0,new Date(load.claim_deadline).getTime()-Date.now());const countdown=priority?`${String(Math.floor(remaining/60000)).padStart(2,"0")}:${String(Math.floor(remaining%60000/1000)).padStart(2,"0")}`:label(load.claim_status);return `<article class="load ${priority?"priority":load.claim_status==="FALLBACK_PENDING"?"fallback":""}"><div class="topline"><span class="badge">${escapeHtml(label(load.shipment_category))}</span><span class="countdown" data-deadline="${escapeHtml(load.claim_deadline||"")}" data-priority="${priority}">${countdown}</span></div><div><h2>${escapeHtml(load.restaurant_name||`Shipment #${load.id}`)}</h2><span class="muted">#${load.id} · ${escapeHtml(label(load.status))}</span></div><div class="route"><i></i><div><small>Pickup</small><strong>${escapeHtml(load.pickup_address||"Not supplied")}</strong></div><i></i><div><small>Deliver</small><strong>${escapeHtml(load.delivery_address||"Not supplied")}</strong></div></div><div class="muted">${escapeHtml(load.customer_name||"Customer pending")}${load.fallback_provider?` · ${escapeHtml(label(load.fallback_provider))}`:""}</div>${priority||load.claim_status==="FALLBACK_PENDING"?`<div class="actions"><button data-action="claim" data-id="${load.id}">Claim for LCS</button><button class="release" data-action="release" data-id="${load.id}">Release</button></div>`:""}</article>`}
function updateCountdowns(){document.querySelectorAll("[data-priority='true']").forEach(node=>{const left=Math.max(0,new Date(node.dataset.deadline).getTime()-Date.now());node.textContent=`${String(Math.floor(left/60000)).padStart(2,"0")}:${String(Math.floor(left%60000/1000)).padStart(2,"0")}`})}
function showLogin(){$("signin").hidden=false;$("board").hidden=true;$("adminKey").focus()}
function message(text,error=false){$("message").textContent=text;$("message").style.color=error?"#ff9d8c":"#f4b942"}
function label(value){return String(value||"").replaceAll("_"," ").toLowerCase().replace(/\b\w/g,x=>x.toUpperCase())}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]))}
setInterval(updateCountdowns,1000);setInterval(()=>refresh(),5000);if(state.key)refresh(true);else showLogin();
